// ShowFileDigested is ShowFileBounded for the callers whose contract is not
// merely "refuse an oversized blob" but "refuse it and still say what it was".
// That is the contract BatchFileReader already meets for the paths it CAN carry:
// a blob above the cap is streamed past into a digest and recorded, so the
// caller keeps the file's size, content hash and line count without ever holding
// its bytes. A path the line protocol cannot carry falls back to this argv-based
// reader instead, and until it did the same thing the fallback had to choose
// between an unbounded read and dropping the file with no explanation.
//
// scan, when non-nil, receives successive chunks of a REFUSED blob as they are
// discarded — the same single pass the digest makes, so relevance costs no extra
// read. The bytes are BORROWED: scan must not retain the slice, and chunks may
// split a token, so a caller matching multi-byte patterns must carry its own
// overlap. It is never called for a blob that is returned.
//
// The digest is meaningful only together with ok==false and a nil error; every
// other outcome returns the zero value.
func ShowFileDigested(ctx context.Context, repo, rev, path string, maxBytes int64, scan func(chunk []byte)) (content string, ok bool, refused OversizeBlob, err error) {
	if maxBytes <= 0 {
		content, ok, err = ShowFile(ctx, repo, rev, path)
		return content, ok, OversizeBlob{}, err
	}
	// Same best-effort probe as showFileBounded: when it answers, the blob is
	// refused before a byte of it is materialized.
	if size, known := blobSizeAtRev(ctx, repo, rev, path); known && size > maxBytes {
		digest, digestErr := streamBlobDigest(ctx, repo, rev, path, scan)
		if digestErr != nil {
			return "", false, OversizeBlob{}, digestErr
		}
		return "", false, digest, nil
	}
	// The probe said nothing, so the ceiling can only be applied to the answer.
	// The bytes are already in hand at this point, so the digest is taken from
	// them rather than by reading the blob a second time.
	content, ok, err = ShowFile(ctx, repo, rev, path)
	if err != nil || !ok {
		return "", false, OversizeBlob{}, err
	}
	if int64(len(content)) > maxBytes {
		if scan != nil {
			scan([]byte(content))
		}
		digest, digestErr := filedigest.Stream(strings.NewReader(content))
		if digestErr != nil {
			return "", false, OversizeBlob{}, digestErr
		}
		return "", false, OversizeBlob{Bytes: digest.Bytes, Hash: digest.Hash, Lines: digest.Lines}, nil
	}
	return content, true, OversizeBlob{}, nil
}

// streamBlobDigest digests rev:path without ever holding it, by reading git's
// stdout to EOF through the digest rather than into a buffer.
//
// It reads to EOF deliberately: stopping git early and killing it deadlocked on
// Windows, where a grandchild holding the inherited stderr handle kept the
// copier goroutine from seeing EOF and Cmd.Wait blocked forever (see
// ShowFileLimited). Nothing here depends on process-tree teardown — the pipe
// closes because git finished.
func streamBlobDigest(ctx context.Context, repo, rev, path string, scan func(chunk []byte)) (OversizeBlob, error) {
	objectSpec := rev + "^{tree}:" + path
	cmd := newCmd(ctx, repo, "git", "cat-file", "blob", objectSpec)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return OversizeBlob{}, err
	}
	if err := cmd.Start(); err != nil {
		return OversizeBlob{}, err
	}
	var src io.Reader = stdout
	if scan != nil {
		src = io.TeeReader(src, scanWriter{scan: scan})
	}
	digest, digestErr := filedigest.Stream(src)
	// Drain whatever the digest did not consume, so git is never writing into a
	// full pipe when Wait is called.
	_, _ = io.Copy(io.Discard, stdout)
	waitErr := cmd.Wait()
	if digestErr != nil {
		return OversizeBlob{}, digestErr
	}
	if waitErr != nil {
		msg := strings.TrimSpace(stderr.String())
		if msg == "" {
			msg = waitErr.Error()
		}
		return OversizeBlob{}, fmt.Errorf("git cat-file blob %s: %s", objectSpec, msg)
	}
	return OversizeBlob{Bytes: digest.Bytes, Hash: digest.Hash, Lines: digest.Lines}, nil
}

// scanWriter adapts a chunk callback to io.Writer so it can sit in the TeeReader
// on the streaming path. Write must not retain p, and the callback is documented
// not to.
type scanWriter struct {
	scan func(chunk []byte)
}

func (w scanWriter) Write(p []byte) (int, error) {
	w.scan(p)
	return len(p), nil
}

// blobSizeAtRev reports the size of the blob at rev:path without reading it.
// It is BEST EFFORT by design: known=false means "no answer", never "absent" or
// "broken", so a caller can only use it to refuse, not to conclude.
func blobSizeAtRev(ctx context.Context, repo, rev, path string) (int64, bool) {
	out, _, err := runWithStderr(ctx, repo, "git", "cat-file", "-s", rev+"^{tree}:"+path)
	if err != nil {
		return 0, false
	}
	size, parseErr := strconv.ParseInt(strings.TrimSpace(out), 10, 64)
	if parseErr != nil {
		return 0, false
	}
	return size, true
}

func isMissingPathDiagnostic(stderr string) bool {
	// ShowFile runs git under the C locale, so only classify Git's specific
	// missing-path diagnostics. Broad substring checks can match a bad revision
	// or an unrelated error merely because an argv value contains the phrase.
	return strings.HasPrefix(stderr, "fatal: path '") &&
		(strings.Contains(stderr, "' does not exist in '") ||
			strings.Contains(stderr, "' exists on disk, but not in '"))
}

// BatchFileReader reads blobs from one revision through a persistent
// `git cat-file --batch` process. It avoids spawning one git process per file
// while preserving HEAD-tree snapshot semantics.
type BatchFileReader struct {
	rev          string
	cmd          *exec.Cmd
	stdin        io.WriteCloser
	stdout       *bufio.Reader
	stderr       *bytes.Buffer
	mu           sync.Mutex
	closed       bool
	maxBytes     int64
	oversize     map[string]OversizeBlob
	oversizeScan func(path string, chunk []byte)
}

// OversizeBlob describes a blob ReadFile refused to materialize because it
// exceeds the reader's cap. The hash and line count are computed while the blob
// is streamed past and discarded, so a caller can still record the file's
// identity and shape without ever holding its bytes.
type OversizeBlob struct {
	Bytes int64
	Hash  string
	Lines int
}

// SetOversizeScanner registers a callback invoked with successive chunks of an OVERSIZE blob as it
// streams past the reader and is discarded. It exists so a caller can decide whether a blob it will
// never hold was nonetheless relevant: the dependents scan needs to know whether an oversized file
// contained a changed name, because warning about a file that never was a candidate is noise. The
// bytes are BORROWED - the callback must not retain the slice. Chunks arrive in order and may split
// a token, so a caller matching multi-byte patterns must carry its own overlap.
func (r *BatchFileReader) SetOversizeScanner(scan func(path string, chunk []byte)) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.oversizeScan = scan
}

// SetMaxBytes caps the blob size ReadFile will materialize. A larger blob is
// streamed past the reader into a digest and discarded: ReadFile reports it as
// unavailable and OversizeBlob then returns its size, content hash and line
// count. Without a cap one oversized blob costs its own size twice (the byte
// slice plus the string conversion), so the reader's memory is set by the
// largest object in the revision rather than by anything the caller chose. Zero
// or negative removes the cap.
func (r *BatchFileReader) SetMaxBytes(maxBytes int64) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.maxBytes = maxBytes
}

// OversizeBlob returns what ReadFile learned about a blob it refused to
// materialize, so the caller can record the file without its content.
func (r *BatchFileReader) OversizeBlob(path string) (OversizeBlob, bool) {
	r.mu.Lock()
	defer r.mu.Unlock()
	blob, ok := r.oversize[path]
	return blob, ok
}

func NewBatchFileReader(ctx context.Context, repo, rev string) (*BatchFileReader, error) {
	// The request is "<rev>:<path>\n", so the REVISION shares the line with the
	// path and a revision holding a newline splits every request the reader will
	// ever make. Git accepts such revisions — `HEAD^{/subject\nbody}` resolves
	// against a multi-line commit message — and `graph diff --head` passes its
	// value through unchanged, so this is reachable from the command line.
	//
	// Refusing the reader would turn a revision git accepts into a hard failure,
	// so resolve it instead: rev is only ever used as the request prefix, and an
	// object id names the same commit in a form the line protocol can carry. The
	// ordinary revision skips this entirely, so the fast path keeps costing
	// nothing.
	// Only a newline is handled here. A carriage return inside the revision
	// round-trips intact, because git strips at most one CR from the END of the
	// line and ":<path>" always follows the revision — the one case where it
	// could land there, an empty path, is caught by ReadFile's own check below.
	if strings.Contains(rev, "\n") {
		resolved, err := RevParse(ctx, repo, rev)
		if err != nil {
			return nil, fmt.Errorf("resolve revision for git cat-file --batch: %w", err)
		}
		if strings.Contains(resolved, "\n") {
			return nil, fmt.Errorf("%w: revision %q does not resolve to a single object id", ErrNonBatchablePath, rev)
		}
		rev = resolved
	}
	cmd := newCmd(ctx, repo, "git", "cat-file", "--batch")
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return nil, err
	}
	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		_ = stdin.Close()
		return nil, err
	}
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	if err := cmd.Start(); err != nil {
		_ = stdin.Close()
		return nil, fmt.Errorf("git cat-file --batch: %w", err)
	}
	return &BatchFileReader{
		rev:    rev,
		cmd:    cmd,
		stdin:  stdin,
		stdout: bufio.NewReader(stdoutPipe),
		stderr: &stderr,
	}, nil
}

