	t.Helper()
	return Run(t.Context(), Options{
		Version: "test-version",
		Env:     EntireEnv{RepoRoot: repo, PluginDataDir: t.TempDir()},
		Stdout:  &bytes.Buffer{},
	}, []string{"index", "--repo", repo, "--format", "json", "--report", report})
}

